"""Batch enqueue and folder scan helpers."""

from __future__ import annotations

import uuid
from pathlib import Path
from typing import Any

DEFAULT_MEDIA_EXTENSIONS = frozenset(
    {
        ".mp4",
        ".mkv",
        ".avi",
        ".mov",
        ".webm",
        ".m4v",
        ".ts",
        ".m2ts",
        ".wmv",
        ".flv",
        ".wav",
        ".mp3",
        ".flac",
        ".ogg",
        ".m4a",
        ".aac",
        ".wma",
        ".opus",
    }
)


def normalize_extensions(raw: Any) -> set[str]:
    if not raw:
        return set(DEFAULT_MEDIA_EXTENSIONS)
    out: set[str] = set()
    items = raw if isinstance(raw, (list, tuple, set)) else str(raw).split(",")
    for item in items:
        ext = str(item or "").strip().lower()
        if not ext:
            continue
        if not ext.startswith("."):
            ext = f".{ext}"
        out.add(ext)
    return out or set(DEFAULT_MEDIA_EXTENSIONS)


def scan_media_files(
    folder: str | Path,
    *,
    recursive: bool = True,
    extensions: Any = None,
    limit: int = 500,
) -> list[Path]:
    root = Path(folder)
    if not root.is_dir():
        raise FileNotFoundError(f"folder not found: {folder}")
    exts = normalize_extensions(extensions)
    cap = max(1, min(2000, int(limit or 500)))
    found: list[Path] = []
    iterator = root.rglob("*") if recursive else root.iterdir()
    for path in iterator:
        try:
            if not path.is_file():
                continue
            if path.suffix.lower() not in exts:
                continue
            found.append(path.resolve())
            if len(found) >= cap:
                break
        except OSError:
            continue
    found.sort(key=lambda p: str(p).lower())
    return found


def build_batch_requests(
    media_paths: list[str],
    template: dict[str, Any] | None = None,
    *,
    batch_id: str | None = None,
    per_item: list[dict[str, Any]] | None = None,
) -> tuple[str, list[dict[str, Any]]]:
    """
    Build job requests for a batch.

    ``template`` supplies shared fields; each media path gets its own request.
    ``per_item`` optional list of overrides aligned with media_paths (or dicts with mediaPath).
    """
    bid = (batch_id or uuid.uuid4().hex[:10]).strip() or uuid.uuid4().hex[:10]
    base = dict(template or {})
    base.pop("mediaPath", None)
    base.pop("sync", None)
    base.pop("mediaPaths", None)
    reqs: list[dict[str, Any]] = []

    paths = [str(p).strip() for p in (media_paths or []) if str(p).strip()]
    if per_item and not paths:
        for item in per_item:
            if not isinstance(item, dict):
                continue
            mp = str(item.get("mediaPath") or "").strip()
            if not mp:
                continue
            paths.append(mp)

    for i, media in enumerate(paths):
        req = dict(base)
        override: dict[str, Any] = {}
        if per_item and i < len(per_item) and isinstance(per_item[i], dict):
            override = dict(per_item[i])
            override.pop("sync", None)
        req.update(override)
        req["mediaPath"] = str(override.get("mediaPath") or media)
        req["batchId"] = bid
        req["batchIndex"] = i
        req["batchTotal"] = len(paths)
        # Default output beside media unless template/override set outputDir
        if not req.get("outputDir"):
            req["outputDir"] = str(Path(req["mediaPath"]).parent)
        reqs.append(req)
    return bid, reqs


def write_words_json(
    cues: list[dict[str, Any]],
    output_path: str | Path,
) -> Path:
    """Write word-level timing JSON derived from cue.words (or empty words arrays)."""
    import json

    path = Path(output_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = {
        "version": 1,
        "cueCount": len(cues or []),
        "cues": [
            {
                "start": c.get("start"),
                "end": c.get("end"),
                "text": c.get("text"),
                "words": c.get("words") or [],
            }
            for c in (cues or [])
            if isinstance(c, dict)
        ],
    }
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return path


def summarize_batch(batch_id: str, jobs: list[Any]) -> dict[str, Any]:
    """Aggregate status counts for a batch of JobState-like objects / snapshots."""
    counts = {
        "queued": 0,
        "running": 0,
        "done": 0,
        "error": 0,
        "cancelled": 0,
        "other": 0,
    }
    items: list[dict[str, Any]] = []
    for job in jobs or []:
        if hasattr(job, "status"):
            status = str(getattr(job, "status", "") or "other")
            jid = getattr(job, "id", None)
            req = getattr(job, "request", {}) or {}
            err = getattr(job, "error", None)
            result = getattr(job, "result", None)
        elif isinstance(job, dict):
            status = str(job.get("status") or "other")
            jid = job.get("id")
            req = job.get("request") or {}
            err = job.get("error")
            result = job.get("result") or job.get("resultSummary")
        else:
            continue
        key = status if status in counts else "other"
        counts[key] = counts.get(key, 0) + 1
        items.append(
            {
                "id": jid,
                "status": status,
                "mediaPath": req.get("mediaPath") if isinstance(req, dict) else None,
                "batchIndex": req.get("batchIndex") if isinstance(req, dict) else None,
                "error": err,
                "outputs": (result or {}).get("outputs") if isinstance(result, dict) else None,
            }
        )
    total = sum(counts.values())
    finished = counts["done"] + counts["error"] + counts["cancelled"]
    return {
        "batchId": batch_id,
        "total": total,
        "finished": finished,
        "counts": counts,
        "percent": int(100 * finished / total) if total else 0,
        "jobs": sorted(
            items,
            key=lambda x: (
                x.get("batchIndex") is None,
                x.get("batchIndex") if x.get("batchIndex") is not None else 0,
            ),
        ),
    }
